private void writeMenuProperties(StringBuilder props, String identification, String version) {
    if (!grayService.isInMenuWebH5GroupWhitelist(identification, version)) {
        return;                        // 未命中灰度不写这段属性，导出包与老版本完全一致
    }
    List<String> h5Codes = componentMenuDao.queryTopH5MenuCodes(identification, version);
    if (h5Codes.isEmpty()) {
        return;
    }
    // 只写 code 列表，不写结构：结构留在 menus.xml 里保持平铺
    props.append("  <property id=\"menu.H5List\" value=\"")
            .append(String.join(",", h5Codes))
            .append("\"/>")
            .append(System.lineSeparator());
}

// menus.xml 恒为存量平铺格式：一级菜单直接挂根下，不生成任何分组壳节点

private void restoreMenuGroup(List<MenuNode> nodes, Properties props, boolean legacyShell) {
    if (legacyShell) {
        // 存量灰度包：壳节点已经表达分组，按壳往下传播
        for (MenuNode node : nodes) {
            if (MENU_GROUP_VALUES.contains(node.getGroupTag())) {
                propagateGroup(node, node.getGroupTag());
                continue;
            }
            restoreMenuGroup(node.getChildren(), props, true);
        }
        return;
    }
    // 新格式包：按 menu.H5List 里的 code 打标
    String h5List = props.getProperty("menu.H5List");
    if (StringUtils.isBlank(h5List)) {
        return;
    }
    Set<String> h5Codes = Arrays.stream(h5List.split(","))
            .map(String::trim).filter(StringUtils::isNotBlank)
            .collect(Collectors.toSet());
    markByCodes(nodes, h5Codes);
}
